package practice;

import java.util.concurrent.BlockingQueue;

/**
 * Delivers the payloads in an outbox to a customer's webhook, one at a time. A failed delivery is
 * retried, with a growing pause between attempts. Runs on a thread of the notification pool,
 * which is shut down with shutdownNow() on every deploy.
 */
public class WebhookSender implements Runnable {

    /** One POST to the customer's endpoint; true when they accepted it. */
    public interface Endpoint {
        boolean post(String payload);
    }

    /** Waits the given time. In production this is Thread::sleep. */
    public interface Pause {
        void pause(long millis) throws InterruptedException;
    }

    private final BlockingQueue<String> outbox;
    private final Endpoint endpoint;
    private final Pause pause;
    private final int maxAttempts;

    public WebhookSender(BlockingQueue<String> outbox, Endpoint endpoint, Pause pause, int maxAttempts) {
        this.outbox = outbox;
        this.endpoint = endpoint;
        this.pause = pause;
        this.maxAttempts = maxAttempts;
    }

    public WebhookSender(BlockingQueue<String> outbox, Endpoint endpoint) {
        this(outbox, endpoint, Thread::sleep, 5);
    }

    /** Delivers payloads from the outbox, oldest first, for as long as the sender runs. */
    @Override
    public void run() {
        try {
            while (!Thread.currentThread().isInterrupted()) {
                deliver(outbox.take());
            }
        } catch (InterruptedException e) {
            Thread.currentThread().interrupt();
        }
    }

    /** Delivers one payload, retrying a failure. True when the endpoint accepted it. */
    boolean deliver(String payload) {
        for (int attempt = 1; attempt <= maxAttempts; attempt++) {
            if (endpoint.post(payload)) return true;
            if (attempt == maxAttempts || !backOff(attempt)) return false;
        }
        return false;
    }

    /** Waits before the attempt after {@code attempt}. False when the sender must not retry. */
    boolean backOff(int attempt) {
        try {
            pause.pause(200L * attempt);
            return true;
        } catch (InterruptedException e) {
            Thread.currentThread().interrupt();
            return false;
        }
    }
}

package practice;

import java.util.ArrayList;
import java.util.Collections;
import java.util.List;
import java.util.concurrent.BlockingQueue;
import java.util.concurrent.CountDownLatch;
import java.util.concurrent.ExecutorService;
import java.util.concurrent.Executors;
import java.util.concurrent.LinkedBlockingQueue;
import java.util.concurrent.TimeUnit;
import java.util.concurrent.atomic.AtomicReference;
import java.util.logging.ConsoleHandler;
import java.util.logging.Level;
import java.util.logging.Logger;

/** Run executes this file. Change the calls in main and see what prints. Submit grades. */
public class TryIt {
    /** Held here, so the JDK's own exit notice stays off: a logger nothing holds can be dropped. */
    private static final Logger JDK_EXIT = Logger.getLogger("java.lang.Runtime");

    public static void main(String[] args) throws Exception {
        // Turn the logger up, so the log lines of your code show under the printed lines.
        System.setProperty("java.util.logging.SimpleFormatter.format", "%4$s %5$s%n");
        // Only this handler prints, and it leaves out the JDK's own detail.
        Logger root = Logger.getLogger("");
        for (java.util.logging.Handler before : root.getHandlers()) {
            root.removeHandler(before);
        }
        ConsoleHandler handler = new ConsoleHandler();
        handler.setLevel(Level.ALL);
        handler.setFilter(entry -> !String.valueOf(entry.getLoggerName()).matches("(java|javax|jdk|sun|com\\.sun)\\..*"));
        root.setLevel(Level.ALL);
        root.addHandler(handler);
        JDK_EXIT.setLevel(Level.OFF);

        // A stand-in for the collaborator, like the one the tests use for the first main case.
        try {
            BlockingQueue<String> outbox = new LinkedBlockingQueue<>(List.of("order.shipped#41", "order.shipped#42"));
            List<String> posts = Collections.synchronizedList(new ArrayList<>());
            List<Long> pauses = Collections.synchronizedList(new ArrayList<>());
            CountDownLatch bothDelivered = new CountDownLatch(2);
            WebhookSender.Endpoint endpoint = payload -> {
                posts.add(payload);
                boolean accepted = !(payload.endsWith("#41") && posts.size() < 3);
                if (accepted) bothDelivered.countDown();
                return accepted;
            };
            AtomicReference<Throwable> failure = new AtomicReference<>();
            ExecutorService pool = Executors.newSingleThreadExecutor(r -> {
                Thread t = new Thread(r, "webhooks");
                t.setDaemon(true);
                t.setUncaughtExceptionHandler((thread, e) -> failure.set(e));
                return t;
            });
            pool.execute(new WebhookSender(outbox, endpoint, millis -> {
                pauses.add(millis);
                if (Thread.interrupted()) throw new InterruptedException();
            }, 4));
            for (int i = 0; i < 50 && failure.get() == null && !bothDelivered.await(100, TimeUnit.MILLISECONDS); i++) { }
            if (failure.get() instanceof RuntimeException e) throw e;
            System.out.println("both delivered: " + (bothDelivered.getCount() == 0));
            pool.shutdownNow();
            System.out.println("sender ended on shutdownNow: " + pool.awaitTermination(5, TimeUnit.SECONDS));
            System.out.println("requests sent: " + posts);
            System.out.println("pauses taken (ms): " + pauses);
        } catch (RuntimeException stopped) {
            // A method you have not finished, or a bug, stops here with its message, not a build error.
            System.out.println("Run stopped: " + stopped);
        }
    }
}

